package com.vishal.ticketbooking.entity;

import jakarta.persistence.*;
import java.time.LocalDateTime;

// This class becomes the "bookings" table in PostgreSQL.
@Entity
@Table(name = "bookings")
public class Booking {

    // Primary key, auto-generated by PostgreSQL.
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Who made the booking. We store just the user's ID (no User table in this project).
    @Column(name = "user_id", nullable = false)
    private Long userId;

    // Many bookings can point to one seat over time (e.g. booked, cancelled, booked again).
    // This creates the seat_id foreign key.
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "seat_id", nullable = false)
    private Seat seat;

    // Stored as text: "CONFIRMED", "FAILED" or "CANCELLED".
    @Enumerated(EnumType.STRING)
    @Column(name = "booking_status", nullable = false)
    private BookingStatus bookingStatus;

    // When the booking was made. updatable = false -> never changes after creation.
    @Column(name = "created_at", nullable = false, updatable = false)
    private LocalDateTime createdAt;

    // Required by Hibernate to build objects from DB rows.
    public Booking() {
    }

    // Convenience constructor used when creating a new booking.
    public Booking(Long userId, Seat seat, BookingStatus bookingStatus) {
        this.userId = userId;
        this.seat = seat;
        this.bookingStatus = bookingStatus;
    }

    // @PrePersist runs automatically just BEFORE the row is first saved.
    // It stamps the creation time so we never forget to set it.
    @PrePersist
    protected void onCreate() {
        this.createdAt = LocalDateTime.now();
    }

    // Getters and setters.
    public Long getId() { return id; }

    public Long getUserId() { return userId; }
    public void setUserId(Long userId) { this.userId = userId; }

    public Seat getSeat() { return seat; }
    public void setSeat(Seat seat) { this.seat = seat; }

    public BookingStatus getBookingStatus() { return bookingStatus; }
    public void setBookingStatus(BookingStatus bookingStatus) { this.bookingStatus = bookingStatus; }

    public LocalDateTime getCreatedAt() { return createdAt; }
}